JOIN public.bank_accounts b ON b.name = v.bank
ON CONFLICT (dedupe_key) DO UPDATE SET
  txn_date=EXCLUDED.txn_date, ref_no=EXCLUDED.ref_no, description=EXCLUDED.description,
  amount=EXCLUDED.amount, direction=EXCLUDED.direction, bucket=EXCLUDED.bucket,
  company=EXCLUDED.company, segment=EXCLUDED.segment, media_type=EXCLUDED.media_type,
  raw_tag=EXCLUDED.raw_tag, updated_at=now();

NOTIFY pgrst, 'reload schema';

-- ============================ VERIFY ============================
-- expect: 1060 import rows, operating ~ -43,260 (breakeven)
SELECT bucket, count(*) n, sum(amount) total
  FROM public.finance_transactions WHERE source='import' GROUP BY 1 ORDER BY total DESC;

SELECT
  (SELECT sum(amount) FROM public.finance_transactions WHERE bucket='income')                          AS income,
  (SELECT sum(amount) FROM public.finance_transactions WHERE bucket='direct_cost')                     AS direct_cost,
  (SELECT sum(amount) FROM public.finance_transactions WHERE bucket='common_expense')                  AS common,
  (SELECT sum(amount) FROM public.finance_transactions WHERE bucket='income')
   - (SELECT sum(amount) FROM public.finance_transactions WHERE bucket IN ('direct_cost','common_expense')) AS operating_profit;

-- segment split (before common allocation)
SELECT segment,
       sum(amount) FILTER (WHERE bucket='income')      AS income,
       sum(amount) FILTER (WHERE bucket='direct_cost') AS direct_cost
  FROM public.finance_transactions
 WHERE bucket IN ('income','direct_cost') AND segment IS NOT NULL
 GROUP BY segment;
